insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-19', 'Press + Steady Twelve', 'Press · steady conditioning', 'Cycle 1, week 1: starting-point week. Nobody has logged lifts yet, so every lift day builds to a solid set of 5, not a max. Log it, and from week 2 the app shows each person their own weights.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "versions": ["2 rounds: 200 m row or easy jog · 10 band pull-aparts · 10 arm circles each way · 5 empty-bar presses", "2 rounds: 200 m row or easy jog · 10 band pull-aparts · 10 arm circles each way · 5 empty-bar presses", "2 rounds: 200 m row or easy jog · 10 band pull-aparts · 10 arm circles each way · 5 empty-bar presses", "2 rounds: 200 m row or easy jog · 10 band pull-aparts · 10 arm circles each way · 5 empty-bar presses"], "minutes": 10}, {"kind": "strength", "label": "Strength · find your starting point", "title": "Strict press: find your 5", "versions": ["Dumbbell press: 4 × 10, building to a weight you could lift about 12 times\nLog your heaviest set.", "Strict press: build over 5 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Strict press: build over 5–6 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Strict press: build over 6 sets to a heavy set of 5\nPerfect reps only. Log it."], "lift": {"movement": "Strict press", "pct": [null, null, null, null], "reps": 5, "gentleMovement": "Dumbbell press", "mode": "build"}}, {"kind": "conditioning", "label": "Conditioning", "title": "Steady Twelve", "versions": ["As many rounds as you can in 12 min, easy pace:\n150 m row · 8 box sit-to-stands · 8 wall push-ups", "As many rounds as you can in 12 min:\n200 m row · 10 air squats · 8 knee push-ups", "As many rounds as you can in 12 min:\n250 m row · 15 kettlebell swings (26/35 lb) · 10 push-ups", "As many rounds as you can in 14 min:\n300 m row · 20 kettlebell swings (35/53 lb) · 15 push-ups"], "minutes": 12, "outdoor": {"title": "Steady Twelve, Outside", "versions": ["As many rounds as you can in 12 min, easy pace:\n150 m brisk walk · 8 box sit-to-stands · 8 wall push-ups", "As many rounds as you can in 12 min:\n200 m jog · 10 air squats · 8 knee push-ups", "As many rounds as you can in 12 min:\n200 m run · 15 kettlebell swings (26/35 lb) · 10 push-ups", "As many rounds as you can in 14 min:\n300 m run · 20 kettlebell swings (35/53 lb) · 15 push-ups"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "versions": ["Shoulder and chest stretch, 5 min", "Shoulder and chest stretch, 5 min", "Shoulder and chest stretch, 5 min", "Shoulder and chest stretch, 5 min"], "minutes": 5}]'::jsonb, 'published', null)
