insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-20', 'Deadlift + Repeats', 'Deadlift · intervals', 'Cycle 1, week 1: starting-point week. Nobody has logged lifts yet, so every lift day builds to a solid set of 5, not a max. Log it, and from week 2 the app shows each person their own weights.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "versions": ["2 rounds: 200 m row or easy jog · 10 hip hinges with a dowel · 10 glute bridges · 5 light deadlifts", "2 rounds: 200 m row or easy jog · 10 hip hinges with a dowel · 10 glute bridges · 5 light deadlifts", "2 rounds: 200 m row or easy jog · 10 hip hinges with a dowel · 10 glute bridges · 5 light deadlifts", "2 rounds: 200 m row or easy jog · 10 hip hinges with a dowel · 10 glute bridges · 5 light deadlifts"], "minutes": 10}, {"kind": "strength", "label": "Strength · find your starting point", "title": "Deadlift: find your 5", "versions": ["Kettlebell deadlift: 4 × 10, building to a weight you could lift about 12 times\nLog your heaviest set.", "Deadlift: build over 5 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Deadlift: build over 5–6 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Deadlift: build over 6 sets to a heavy set of 5\nPerfect reps only. Log it."], "lift": {"movement": "Deadlift", "pct": [null, null, null, null], "reps": 5, "gentleMovement": "Kettlebell deadlift", "mode": "build"}}, {"kind": "conditioning", "label": "Conditioning", "title": "Row Repeats", "versions": ["4 rounds: 150 m row at an easy-moderate pace, rest 2 min", "5 rounds: 250 m row, rest 2 min", "6 rounds: 250 m row hard, rest 1:30", "8 rounds: 250 m row hard, rest 1:15"], "minutes": 18, "outdoor": {"title": "Run Repeats", "versions": ["4 rounds: 2 min brisk walk, then 2 min easy walk", "5 rounds: 200 m jog, walk back to recover", "6 rounds: 200 m run hard, walk back to recover", "8 rounds: 200 m run hard,