insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-21', 'Pull-up Check-in + Steady 25', 'Pull-up skills · longer cardio', 'Cycle 1, week 1. A pull-up check-in so we know where everyone starts on the pull-up goal, then a long steady piece.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "versions": ["2 rounds: 3 min bike or jog · 10 scap pull-ups or hangs · 10 ring rows · 10 band pull-aparts", "2 rounds: 3 min bike or jog · 10 scap pull-ups or hangs · 10 ring rows · 10 band pull-aparts", "2 rounds: 3 min bike or jog · 10 scap pull-ups or hangs · 10 ring rows · 10 band pull-aparts", "2 rounds: 3 min bike or jog · 10 scap pull-ups or hangs · 10 ring rows · 10 band pull-aparts"], "minutes": 10}, {"kind": "skill", "label": "Skill · check-in", "title": "Pull-up check-in", "versions": ["Max ring rows in 1 min, feet far back. Write down your number.\nThen 3 × 15 s dead hang.", "Max ring rows in 1 min, feet close in. Write it down.\nThen 3 × 5 band pull-ups with a heavy band.", "Max band pull-ups in one go with your lightest band. Note the band and reps.\nThen 3 × 3 slow lowering pull-ups (5 s down).", "Max strict pull-ups in one go. Write down your number.\nThen 3 × 3 slow lowering pull-ups (5 s down)."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Steady 25", "versions": ["15 min at an easy pace, keep moving:\n8 cal bike · 8 step-ups · 8 ring rows (feet far back)", "20 min at a steady pace:\n10 cal bike · 10 step-ups · 10 ring rows", "25 min at a steady pace:\n12 cal bike · 12 box step-ups (20 in) · 10 ring rows", "25 min at a steady pace:\n15 cal bike · 15 box jumps or step-ups (24 in) · 12 ring rows"], "minutes": 25, "outdoor": {"title": "Loop and Station", "versions": ["15 min, easy pace: walk a lap of the block (about 400 m), then 8 step-ups and 8 ring rows. Repeat.", "20 min, steady: brisk walk or jog 400 m, then 10 step-ups and 10 ring rows. Repeat.", "25 min, steady: run 400 m, then 12 box step-ups (20 in) and 10 ring rows. Repeat.", "25 min, steady: run 400 m, then 15 box jumps or step-ups (24 in) and 12 ring rows. Repeat."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "versions": ["Lat and shoulder stretch, 5 min", "Lat and shoulder stretch, 5 min", "Lat and shoulder stretch, 5 min", "Lat and shoulder stretch, 5 min"], "minutes": 5}]'::jsonb, 'published', null)
