insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-22', 'Easy Day: Walk and Mobility', 'Easy day · mobility + steady pace', 'Cycle 1, week 1. Easy day between the hard ones, so everyone can come every day without wearing down. If it''s nice out, walk.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "versions": ["5 min easy bike, then 2 rounds: 10 cat-cows · 10 hip circles each way · 5 inchworms", "5 min easy bike, then 2 rounds: 10 cat-cows · 10 hip circles each way · 5 inchworms", "5 min easy bike, then 2 rounds: 10 cat-cows · 10 hip circles each way · 5 inchworms", "5 min easy bike, then 2 rounds: 10 cat-cows · 10 hip circles each way · 5 inchworms"], "minutes": 10}, {"kind": "conditioning", "label": "Steady pace", "title": "Bike and Balance", "versions": ["3 rounds: 4 min easy bike · 10 heel raises · 20 s single-leg stand each side", "4 rounds: 4 min easy bike · 15 heel raises · 30 s single-leg stand each side", "4 rounds: 5 min easy bike · 20 heel raises · 10 slow step-downs each side", "5 rounds: 5 min easy bike · 20 single-leg heel raises · 10 slow step-downs each side"], "minutes": 22, "outdoor": {"title": "Walk and Talk", "versions": ["20 min walk at a chatting pace, then 3 × 20 s single-leg stand each side", "25 min brisk walk, then 3 × 30 s single-leg stand each side", "25 min brisk walk carrying a light kettlebell for 1 min every 5 min", "30 min brisk walk or easy jog with a 35 lb carry for 1 min every 5 min"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Mobility", "versions": ["10 min mobility: hips, ankles, upper back. Go slow and breathe.", "10 min mobility: hips, ankles, upper back. Go slow and breathe.", "10 min mobility: hips, ankles, upper back. Go slow and breathe.", "10 min mobility: hips, ankles, upper back. Go slow and breathe."], "minutes": 10}]'::jsonb, 'published', null)
