insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-23', 'Squat + Crew Benchmark', 'Squat · short and spicy', 'Cycle 1, week 1. Find your squat starting point, then the Crew Benchmark: a short test we repeat in test week (Fri Nov 27) so everyone can see how far they''ve come. Write down your time and whether you ran or rowed.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "versions": ["2 rounds: 200 m row or easy jog · 10 goblet squats · 10 band pull-aparts · 5 empty-bar squats", "2 rounds: 200 m row or easy jog · 10 goblet squats · 10 band pull-aparts · 5 empty-bar squats", "2 rounds: 200 m row or easy jog · 10 goblet squats · 10 band pull-aparts · 5 empty-bar squats", "2 rounds: 200 m row or easy jog · 10 goblet squats · 10 band pull-aparts · 5 empty-bar squats"], "minutes": 10}, {"kind": "strength", "label": "Strength · find your starting point", "title": "Back squat: find your 5", "versions": ["Goblet squat: 4 × 10, building to a weight you could lift about 12 times\nLog your heaviest set.", "Back squat: build over 5 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Back squat: build over 5–6 sets to a solid set of 5\nStop where you could still do 1 or 2 more. Log it.", "Back squat: build over 6 sets to a heavy set of 5\nPerfect reps only. Log it."], "lift": {"movement": "Back squat", "pct": [null, null, null, null], "reps": 5, "gentleMovement": "Goblet squat", "mode": "build"}}, {"kind": "conditioning", "label": "Conditioning · benchmark", "title": "Crew Benchmark", "versions": ["3 rounds for time:\n250 m row · 10 kettlebell deadlifts (15 lb) · 10 incline push-ups (on a box)\nWrite down your time.", "3 rounds for time:\n400 m row · 12 kettlebell swings (18 lb) · 10 knee push-ups\nWrite down your time.", "3 rounds for time:\n500 m row · 15 kettlebell swings (26/35 lb) · 10 push-ups\nWrite down your time.", "3 rounds for time:\n500 m row · 20 kettlebell swings (35/53 lb) · 15 push-ups\nWrite down your time."], "minutes": 15, "outdoor": {"title": "Crew Benchmark, Outside", "versions": ["3 rounds for time:\n200 m brisk walk · 10 kettlebell deadlifts (15 lb) · 10 incline push-ups (on a box)\nWrite down your time.", "3 rounds for time:\n300 m jog · 12 kettlebell swings (18 lb) · 10 knee push-ups\nWrite down your time.", "3 rounds for time:\n400 m run · 15 kettlebell swings (26/35 lb) · 10 push-ups\nWrite down your time.", "3 rounds for time:\n400 m run · 20 kettlebell swings (35/53 lb) · 15 push-ups\nWrite down your time."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "versions": ["Hip and quad stretch, 5 min", "Hip and quad stretch, 5 min", "Hip and quad stretch, 5 min", "Hip and quad stretch, 5 min"], "minutes": 5}]'::jsonb, 'published', null)
